def inserir(t, k, conta):
    i = casa_de(k, t.bits)
    x = olha(t, i, conta)
    while x is not None:
        if x == k:
            break
        i = (i + 1) % t.m
        x = olha(t, i, conta)
    if x is None:
        t.escreve_chave(i, k)
        t.escreve_valor(i, k)
        t.n += 1
    return i
